// Versioned data contracts. Source of truth for schemas/*.schema.json (generated by scripts/generate-schemas.mjs).
import {
  FACTOR_IDS, JUDGMENT_FACTORS, QUANTITY_IDS, LAYER_CATEGORIES, EVIDENCE_KINDS, FACT_KINDS, STAGES,
} from './factors.mjs';

export const KINDS = {
  profile: 'openspec-assess.profile',
  config: 'openspec-assess.config',
  overrides: 'openspec-assess.overrides',
  benchmarks: 'openspec-assess.benchmarks',
  manifest: 'openspec-assess.manifest',
  report: 'openspec-assess.report',
  latest: 'openspec-assess.latest',
};

export const SCHEMA_VERSIONS = {
  profile: 1,
  config: 3,
  overrides: 3,
  benchmarks: 1,
  manifest: 1,
  report: 3,
  latest: 1,
};

const ID = '^[a-z0-9][a-z0-9._-]*$';
const TASK_ID = '^[0-9]+(\\.[0-9]+)*$';
const SHA256 = '^sha256:[0-9a-f]{64}$';
const HEX64 = '^[0-9a-f]{64}$';
const REL_PATH = '^(?!/)(?![A-Za-z]:)(?!.*(^|/)\\.\\.(/|$))[^\\\\\\u0000]+$';
const DATE = '^[0-9]{4}-[0-9]{2}-[0-9]{2}$';
const DATETIME = '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$';
const NON_EMPTY = { type: 'string', minLength: 1 };
const BP = { type: 'integer', minimum: 0, maximum: 10000 };
const NONNEG = { type: 'integer', minimum: 0 };
const LEVEL = { type: 'integer', minimum: 0, maximum: 4 };

function header(kind, version) {
  return {
    kind: { const: KINDS[kind] },
    schemaVersion: { const: version },
  };
}

function strictObject(properties, required = Object.keys(properties)) {
  return { type: 'object', properties, required, additionalProperties: false };
}

function factorMap(valueSchema, factors = FACTOR_IDS) {
  return {
    type: 'object',
    propertyNames: { enum: factors },
    additionalProperties: valueSchema,
  };
}

// ---------------------------------------------------------------- profile
export const profileSchema = {
  $schema: 'https://json-schema.org/draft/2020-12/schema',
  $id: 'https://openspec-assess.local/schemas/profile-1.schema.json',
  title: 'Change assessment profile v1',
  type: 'object',
  additionalProperties: false,
  required: ['kind', 'schemaVersion', 'change', 'stage', 'scope', 'evidence', 'quantities', 'factors'],
  properties: {
    ...header('profile', 1),
    change: strictObject({
      name: { type: 'string', pattern: ID },
      revision: NON_EMPTY,
    }, ['name']),
    stage: { enum: STAGES },
    previousAssessmentId: { type: 'string', pattern: HEX64 },
    scope: {
      type: 'object',
      additionalProperties: false,
      required: ['mode'],
      properties: {
        mode: { enum: ['all-tasks', 'tasks'] },
        taskIds: { type: 'array', items: { type: 'string', pattern: TASK_ID }, minItems: 1, uniqueItems: true },
        note: NON_EMPTY,
      },
    },
    evidence: {
      type: 'array',
      minItems: 1,
      items: { $ref: '#/$defs/evidence' },
    },
    quantities: {
      type: 'object',
      propertyNames: { enum: QUANTITY_IDS },
      additionalProperties: { $ref: '#/$defs/quantity' },
      required: QUANTITY_IDS,
    },
    factors: {
      type: 'object',
      propertyNames: { enum: JUDGMENT_FACTORS },
      additionalProperties: { $ref: '#/$defs/factor' },
      required: JUDGMENT_FACTORS,
    },
    notes: NON_EMPTY,
  },
  $defs: {
    evidence: {
      type: 'object',
      additionalProperties: false,
      required: ['id', 'kind', 'note'],
      properties: {
        id: { type: 'string', pattern: ID },
        kind: { enum: EVIDENCE_KINDS },
        base: { enum: ['change', 'repo'] },
        path: { type: 'string', pattern: REL_PATH },
        locator: NON_EMPTY,
        digest: { type: 'string', pattern: SHA256 },
        revision: NON_EMPTY,
        planned: { type: 'boolean' },
        derivedFrom: { type: 'array', items: { type: 'string', pattern: ID }, minItems: 1, uniqueItems: true },
        note: NON_EMPTY,
      },
    },
    quantity: {
      type: 'object',
      additionalProperties: false,
      required: ['state'],
      properties: {
        state: { enum: ['known', 'unknown', 'not-applicable'] },
        kind: { enum: FACT_KINDS },
        min: NONNEG,
        max: NONNEG,
        rationale: NON_EMPTY,
        evidence: { type: 'array', items: { type: 'string', pattern: ID }, minItems: 1, uniqueItems: true },
      },
    },
    factor: {
      type: 'object',
      additionalProperties: false,
      required: ['state'],
      properties: {
        state: { enum: ['known', 'unknown', 'not-applicable'] },
        level: LEVEL,
        kind: { enum: FACT_KINDS },
        rationale: NON_EMPTY,
        evidence: { type: 'array', items: { type: 'string', pattern: ID }, minItems: 1, uniqueItems: true },
        details: { $ref: '#/$defs/factorDetails' },
      },
    },
    factorDetails: {
      type: 'object',
      additionalProperties: false,
      properties: {
        domainIds: { type: 'array', items: { type: 'string', pattern: ID }, uniqueItems: true },
        links: NONNEG,
        layerCategories: { type: 'array', items: { enum: LAYER_CATEGORIES }, uniqueItems: true },
        boundaryCrossings: NONNEG,
        tags: { type: 'array', items: { type: 'string', pattern: ID }, uniqueItems: true },
      },
    },
  },
};

// ---------------------------------------------------------------- config
export const SELECTION_POLICIES = ['minimum-resource-with-time-penalty', 'weighted-utility'];
export const DEFAULT_TIME_PENALTY = { graceMinutes: 30, intervalMinutes: 30, rateBp: 500 };
export const PROVENANCE_STATUSES = ['measured', 'proxy', 'heuristic', 'unknown', 'user-override'];
// Units of the per-effort resource tables (stored next to the values; 10000 = 1.0×).
export const RESOURCE_UNITS = {
  usage: 'token-workload-multiplier-bp',
  load: 'load-workload-multiplier-bp',
  minutes: 'time-workload-multiplier-bp',
};
const IDS = { type: 'array', items: { type: 'string', pattern: ID }, uniqueItems: true };
const inheritedFrom = strictObject({
  modelId: NON_EMPTY,
  harness: { type: 'string', pattern: ID },
  status: { enum: PROVENANCE_STATUSES },
});
// Record of a v1 value materialised by migrate-config (kept verbatim for provenance).
const migratedFrom = strictObject({
  fromSchemaVersion: { const: 1 },
  rule: { enum: ['byEffort', 'base+delta', 'resource'] },
  base: { type: 'object' },
  effortDelta: { type: 'object' },
  entry: { type: 'object' },
  clamped: { type: 'boolean' },
  note: NON_EMPTY,
}, ['fromSchemaVersion', 'rule', 'note']);

// One estimate: exactly one value (or explicit unknown) for model/harness × phase × effort × factor
// (quality) or × resource kind. `sources` define the number (measured/proxy only); `support` lists
// evidence that backs the general assumption without deriving the number. `origin` keeps the record
// that a user change replaced, with its own identity and sources.
function estimateRecord(valueSchema, withOrigin) {
  const props = {
    value: { anyOf: [valueSchema, { type: 'null' }] },
    status: { enum: PROVENANCE_STATUSES },
    basis: NON_EMPTY,
    sources: IDS,
    support: IDS,
    inheritedFrom,
    migratedFrom,
  };
  if (withOrigin) props.origin = { $ref: withOrigin };
  return { type: 'object', additionalProperties: false, required: ['value', 'status', 'basis'], properties: props };
}
const effortMap = (item) => ({ type: 'object', propertyNames: { pattern: ID }, additionalProperties: item, minProperties: 1 });
const qualityPhase = effortMap({ ...factorMap({ $ref: '#/$defs/qualityRecord' }), required: FACTOR_IDS });
const resourceTable = (unit) => strictObject({
  unit: { const: unit },
  apply: effortMap({ $ref: '#/$defs/resourceRecord' }),
  verify: effortMap({ $ref: '#/$defs/resourceRecord' }),
});

const usage = strictObject({
  uncachedInputTokens: NONNEG,
  cacheReadTokens: NONNEG,
  cacheWriteTokens: NONNEG,
  outputTokens: NONNEG,
  reasoningTokens: NONNEG,
  peakContextTokens: NONNEG,
  toolCalls: { type: 'object', propertyNames: { pattern: ID }, additionalProperties: NONNEG },
}, ['uncachedInputTokens', 'cacheReadTokens', 'cacheWriteTokens', 'outputTokens', 'reasoningTokens', 'peakContextTokens']);

const range3 = (item) => strictObject({ low: item, typical: item, high: item });

const rates = strictObject({
  uncachedInput: { anyOf: [NONNEG, { type: 'null' }] },
  cacheRead: { anyOf: [NONNEG, { type: 'null' }] },
  cacheWrite: { anyOf: [NONNEG, { type: 'null' }] },
  output: { anyOf: [NONNEG, { type: 'null' }] },
  reasoning: { anyOf: [NONNEG, { type: 'null' }] },
});

const categoryMap = (item) => ({ type: 'object', propertyNames: { pattern: ID }, additionalProperties: item, minProperties: 1 });

export const configSchema = {
  $schema: 'https://json-schema.org/draft/2020-12/schema',
  $id: 'https://openspec-assess.local/schemas/config-3.schema.json',
  title: 'Effective assessment configuration v3 (explicit per-effort estimates, explicit selection policy)',
  type: 'object',
  additionalProperties: false,
  required: ['kind', 'schemaVersion', 'catalog', 'complexityRules', 'phases', 'workloads', 'harnesses', 'models', 'pricing', 'quotaPools', 'constraints', 'selection'],
  properties: {
    ...header('config', 3),
    provenance: strictObject({
      defaults: NON_EMPTY,
      overridePaths: { type: 'array', items: { type: 'string' }, uniqueItems: true },
    }, ['defaults', 'overridePaths']),
    catalog: strictObject({
      verifiedAt: { type: 'string', pattern: DATE },
      note: NON_EMPTY,
      sources: { type: 'array', items: strictObject({ id: { type: 'string', pattern: ID }, url: NON_EMPTY, title: NON_EMPTY }) },
    }),
    complexityRules: strictObject({
      volumeThresholds: strictObject({
        tasks: { type: 'array', items: NONNEG, minItems: 4, maxItems: 4 },
        files: { type: 'array', items: NONNEG, minItems: 4, maxItems: 4 },
        diffLines: { type: 'array', items: NONNEG, minItems: 4, maxItems: 4 },
      }),
      groups: strictObject({
        volume: factorMap(NONNEG),
        complexity: factorMap(NONNEG),
        risk: factorMap(NONNEG),
        uncertainty: factorMap(NONNEG),
      }),
      unknownRankingLevel: LEVEL,
      workloadCategories: {
        type: 'array',
        minItems: 1,
        items: strictObject({ id: { type: 'string', pattern: ID }, upToBp: BP }),
      },
      basis: NON_EMPTY,
    }),
    phases: strictObject({
      apply: { $ref: '#/$defs/phase' },
      verify: { $ref: '#/$defs/phase' },
    }),
    workloads: strictObject({
      basis: NON_EMPTY,
      api: strictObject({ apply: categoryMap(range3({ $ref: '#/$defs/usage' })), verify: categoryMap(range3({ $ref: '#/$defs/usage' })) }),
      subscription: strictObject({ apply: categoryMap(range3(NONNEG)), verify: categoryMap(range3(NONNEG)) }),
      timeMinutes: strictObject({ apply: categoryMap(range3(NONNEG)), verify: categoryMap(range3(NONNEG)) }),
    }),
    harnesses: {
      type: 'array',
      minItems: 1,
      items: strictObject({ id: { type: 'string', pattern: ID }, name: NON_EMPTY, docs: NON_EMPTY }, ['id', 'name']),
    },
    models: { type: 'array', items: { $ref: '#/$defs/model' } },
    pricing: { type: 'array', items: { $ref: '#/$defs/pricing' } },
    quotaPools: { type: 'array', items: { $ref: '#/$defs/quotaPool' } },
    constraints: strictObject({
      minContextTokens: { anyOf: [NONNEG, { type: 'null' }] },
      requiredCapabilities: { type: 'array', items: { type: 'string', pattern: ID }, uniqueItems: true },
      api: strictObject({ maxCostMicros: { anyOf: [NONNEG, { type: 'null' }] } }),
    }),
    // Selection policy (config schema 3). "minimum-resource-with-time-penalty": among variants that pass
    // the quality floor and critical factors, minimise S = C × (1 + k × max(0, T − g) / s).
    // "weighted-utility": the legacy 0.1/0.2 rule (quality/economy/time weights with fixed anchors),
    // kept only for configs migrated without an explicit policy switch.
    selection: strictObject({
      policy: { enum: SELECTION_POLICIES },
      policyVersion: { const: 1 },
      api: strictObject({
        currency: { type: 'string', pattern: '^[A-Z]{3}$' },
        weights: { $ref: '#/$defs/selectionWeights' },
        anchors: strictObject({ costMicros: { type: 'integer', minimum: 1 }, timeMinutes: { type: 'integer', minimum: 1 } }),
        timePenalty: { $ref: '#/$defs/timePenalty' },
      }, ['currency']),
      subscription: strictObject({
        weights: { $ref: '#/$defs/selectionWeights' },
        anchors: strictObject({ load: { type: 'integer', minimum: 1 }, timeMinutes: { type: 'integer', minimum: 1 } }),
        timePenalty: { $ref: '#/$defs/timePenalty' },
      }, []),
      basis: NON_EMPTY,
    }),
  },
  $defs: {
    usage,
    phase: strictObject({
      relevanceWeights: { ...factorMap(NONNEG), required: FACTOR_IDS },
      qualityFloors: {
        type: 'array',
        minItems: 1,
        items: strictObject({ fromDemandBp: BP, floorBp: BP }),
      },
      criticalFactors: {
        type: 'array',
        items: strictObject({ factor: { enum: FACTOR_IDS }, whenLevelAtLeast: LEVEL, minCoefficientBp: BP }),
      },
      basis: NON_EMPTY,
    }),
    selectionWeights: strictObject({ quality: NONNEG, economy: NONNEG, time: NONNEG }),
    // g = graceMinutes (no penalty up to and including g), s = intervalMinutes (> 0),
    // k = rateBp / 10000 per interval (0 disables the time penalty). Time T is the typical forecast.
    timePenalty: strictObject({
      graceMinutes: { type: 'integer', minimum: 0, maximum: 100000 },
      intervalMinutes: { type: 'integer', minimum: 1, maximum: 100000 },
      rateBp: { type: 'integer', minimum: 0, maximum: 10000 },
    }),
    qualityRecord: estimateRecord(BP, '#/$defs/qualityOrigin'),
    qualityOrigin: estimateRecord(BP, null),
    resourceRecord: estimateRecord({ type: 'integer', minimum: 0, maximum: 1000000 }, '#/$defs/resourceOrigin'),
    resourceOrigin: estimateRecord({ type: 'integer', minimum: 0, maximum: 1000000 }, null),
    model: {
      type: 'object',
      additionalProperties: false,
      required: ['id', 'family', 'displayName', 'modelId', 'harness', 'clientModelId', 'enabled', 'availability', 'supportedEfforts', 'contextWindowTokens', 'capabilities', 'identity', 'quality', 'resources'],
      properties: {
        id: { type: 'string', pattern: ID },
        family: NON_EMPTY,
        displayName: NON_EMPTY,
        modelId: NON_EMPTY,
        harness: { type: 'string', pattern: ID },
        clientModelId: { anyOf: [NON_EMPTY, { type: 'null' }] },
        enabled: { type: 'boolean' },
        availability: { enum: ['available', 'unavailable', 'unknown'] },
        supportedEfforts: { type: 'array', items: { type: 'string', pattern: ID }, minItems: 1, uniqueItems: true },
        efforts: { type: 'array', items: { type: 'string', pattern: ID }, minItems: 1, uniqueItems: true },
        contextWindowTokens: { anyOf: [NONNEG, { type: 'null' }] },
        capabilities: { anyOf: [{ type: 'array', items: { type: 'string', pattern: ID }, uniqueItems: true }, { type: 'null' }] },
        identity: strictObject({
          status: { enum: ['confirmed', 'unconfirmed'] },
          checkedAt: { type: 'string', pattern: DATE },
          sources: { type: 'array', items: { type: 'string', pattern: ID }, uniqueItems: true },
          note: NON_EMPTY,
        }, ['status', 'checkedAt', 'sources']),
        // Quality estimates, 0–10000 bp (shown as 0–100): quality[phase][effort][factor].
        quality: strictObject({ apply: qualityPhase, verify: qualityPhase }),
        resources: strictObject({
          api: strictObject({ pricingId: { anyOf: [{ type: 'string', pattern: ID }, { type: 'null' }] }, usage: resourceTable(RESOURCE_UNITS.usage) }),
          subscription: strictObject({ poolId: { anyOf: [{ type: 'string', pattern: ID }, { type: 'null' }] }, load: resourceTable(RESOURCE_UNITS.load) }),
          time: strictObject({ minutes: resourceTable(RESOURCE_UNITS.minutes) }),
        }),
      },
    },
    pricing: {
      type: 'object',
      additionalProperties: false,
      required: ['id', 'status', 'currency', 'tier', 'rates', 'reasoningBilling', 'longContext', 'toolCharges'],
      properties: {
        id: { type: 'string', pattern: ID },
        status: { enum: ['confirmed', 'example', 'unknown'] },
        currency: { type: 'string', pattern: '^[A-Z]{3}$' },
        tier: NON_EMPTY,
        source: strictObject({ url: NON_EMPTY, checkedAt: { type: 'string', pattern: DATE } }),
        rates,
        reasoningBilling: { enum: ['as-output', 'separate'] },
        longContext: { anyOf: [{ type: 'null' }, strictObject({ thresholdTokens: { type: 'integer', minimum: 1 }, rates })] },
        toolCharges: { type: 'object', propertyNames: { pattern: ID }, additionalProperties: { anyOf: [NONNEG, { type: 'null' }] } },
        note: NON_EMPTY,
      },
    },
    quotaPool: {
      type: 'object',
      additionalProperties: false,
      required: ['id', 'harness', 'label', 'observation', 'conversion'],
      properties: {
        id: { type: 'string', pattern: ID },
        harness: { type: 'string', pattern: ID },
        label: NON_EMPTY,
        observation: {
          anyOf: [{ type: 'null' }, strictObject({
            observedAt: { type: 'string', pattern: DATETIME },
            maxAgeHours: { type: 'integer', minimum: 1 },
            remaining: NONNEG,
            unit: NON_EMPTY,
            resetAt: { anyOf: [{ type: 'string', pattern: DATETIME }, { type: 'null' }] },
            source: NON_EMPTY,
          })],
        },
        conversion: {
          anyOf: [{ type: 'null' }, strictObject({
            quotaUnitsPer1000Load: { type: 'integer', minimum: 1 },
            unit: NON_EMPTY,
            source: NON_EMPTY,
          })],
        },
        note: NON_EMPTY,
      },
    },
  },
};

